// Service worker of Habit Garden (decision of 19.10.2026: installable and usable offline).
// Generated by scripts/sw.mjs into public/sw.js: __STAMP__ is the build stamp, __FILES__ the paths of every
// deployable file relative to the scope (the shell "./" first). A new build changes the stamp and with it
// the bytes of this file, so the browser installs the new worker next to the old one.
//
// - install: fetches every file with cache "reload" (past the HTTP cache) into the cache "hg-<stamp>".
//   The new worker then waits; the page offers "Neu laden" and sends {type: 'skip-waiting'}.
// - activate: removes the caches of older builds and takes control of open pages.
// - fetch (same origin, GET): a page navigation answers with the cached shell (offline start; the app's
//   router reads the path); other files come from the cache of this build (the ?v= query is ignored: one
//   cache holds one build), else from the network.
/* eslint-disable */
'use strict';

const STAMP = __STAMP__;
const FILES = __FILES__;
const CACHE = `hg-${STAMP}`;
const SHELL = new URL('./', self.registration.scope).href;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await Promise.all(FILES.map(async (path) => {
      const url = new URL(path, self.registration.scope).href;
      const response = await fetch(new Request(url, { cache: 'reload', credentials: 'same-origin' }));
      // The shell may come back as 404.html on GitHub Pages for deep paths; "./" itself is index.html.
      if (!response.ok) throw new Error(`precache ${path}: ${response.status}`);
      await cache.put(url, response);
    }));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('hg-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(self.registration.scope)) return;
  if (request.mode === 'navigate') {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const shell = await cache.match(SHELL);
      if (shell) return shell;
      return fetch(request);
    })());
    return;
  }
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(request, { ignoreSearch: true });
    if (hit) return hit;
    return fetch(request);
  })());
});
